function admin_form(string $action,string $section,string $class=''): void {echo '<form method="post" action="'.e(url('admin',['section'=>$section])).'" class="'.e($class).'">'.csrf_field().'<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="return_section" value="'.e($section).'">';}
function hidden_id(string $name,int $id): void {echo '<input type="hidden" name="'.e($name).'" value="'.$id.'">';}
function options_from(array $rows,string $key='name'): array {$o=[];foreach($rows as $r){$o[$r['id']]=isset($r[$key.'_ar'])?localized($r,$key):$r[$key];}return $o;}
function admin_pager(array $rows,string $section,int $pn): void {if($pn>1 || count($rows)>25){echo '<div class="pagination">';if($pn>1){echo '<a class="button button-outline button-small" href="'.e(url('admin',['section'=>$section,'p'=>$pn-1])).'">'.t('السابق','Previous').'</a>';}echo '<span>'.$pn.'</span>';if(count($rows)>25){echo '<a class="button button-outline button-small" href="'.e(url('admin',['section'=>$section,'p'=>$pn+1])).'">'.t('التالي','Next').'</a>';}echo '</div>';}}
function table_empty(int $columns): void {echo '<tr><td colspan="'.$columns.'" class="table-empty">'.t('لا توجد سجلات حتى الآن.','No records yet.').'</td></tr>';}
